"use client";

import * as React from "react";
import { getToken } from "@/lib/get-token";

// useThemeTokens — reads the chart and palette tokens that apply to a given
// element and returns them as plain hex strings. Re-reads on theme change
// via a MutationObserver on documentElement's data-theme attribute.
//
// Two things make this more than a getPropertyValue call:
//
// 1. SCOPE. The tokens are declared on `.palette-*` elements (global.css:
//    `:root[data-theme] [class*="palette-"]`), never on <html>. Reading
//    documentElement returns "" for every one of them — which is exactly
//    how the chart rendered nothing: every series got color "". The read
//    has to happen on the chart's own element, which also makes the
//    palette scoping work: a `palette-blue` wrapper re-derives chart-1..8
//    from blue for that chart alone.
//
// 2. RESOLUTION. The categorical slots are `oklch(from var(--palette-base)
//    …)` — relative colour syntax. As a custom property that is a token
//    stream, not a colour; and ECharts (zrender) only parses hex/rgb/hsl,
//    so even a resolved `oklch(…)` string would break hover emphasis. A
//    probe element with `color: var(--token)` makes the browser resolve
//    the colour, and a one-pixel canvas round-trip normalises it to hex.
//
// The chart tokens are defined in global.css as CSS custom properties:
//   --chart-1 through --chart-8 (categorical, derived from --palette-base)
//   --chart-ramp-1 through --chart-ramp-5 (ordinal ramp)
//   --palette-base, --palette-soft, --palette-line, --palette-contrast,
//   --palette-accent, --palette-ring (the six roles)

export type ThemeTokens = {
    categorical: string[];
    ramp: string[];
    palette: {
        base: string;
        soft: string;
        line: string;
        contrast: string;
        accent: string;
        ring: string;
    };
};

const CATEGORICAL_KEYS = Array.from(
    { length: 8 },
    (_, i) => `--chart-${i + 1}`,
);
const RAMP_KEYS = Array.from({ length: 5 }, (_, i) => `--chart-ramp-${i + 1}`);

/**
 * Returns `null` until mounted: the tokens live on the DOM, so there is
 * nothing to read on the server or before the scope element exists.
 */
export function useThemeTokens(
    scope?: React.RefObject<HTMLElement | null>,
): ThemeTokens | null {
    const [tokens, setTokens] = React.useState<ThemeTokens | null>(null);

    React.useEffect(() => {
        const read = () => {
            const element = scope?.current ?? document.body;
            setTokens(readTokens(element));
        };
        read();

        const observer = new MutationObserver(read);
        observer.observe(document.documentElement, {
            attributes: true,
            attributeFilter: ["data-theme"],
        });
        return () => observer.disconnect();
    }, [scope]);

    return tokens;
}

function readTokens(scope: HTMLElement): ThemeTokens {
    // The probe inherits the scope's custom properties; `display: none`
    // keeps it out of layout while computed styles still resolve.
    const probe = document.createElement("span");
    probe.style.display = "none";
    scope.appendChild(probe);

    const resolve = (token: string): string => {
        // A token that is not declared in this scope stays "" rather than
        // falling through to the probe's inherited text colour.
        if (!getToken(token, { from: scope, fallbackReturn: "" })) return "";
        probe.style.color = `var(${token})`;
        return toHex(getComputedStyle(probe).color);
    };

    try {
        return {
            categorical: CATEGORICAL_KEYS.map(resolve).filter(Boolean),
            ramp: RAMP_KEYS.map(resolve).filter(Boolean),
            palette: {
                base: resolve("--palette-base"),
                soft: resolve("--palette-soft"),
                line: resolve("--palette-line"),
                contrast: resolve("--palette-contrast"),
                accent: resolve("--palette-accent"),
                ring: resolve("--palette-ring"),
            },
        };
    } finally {
        probe.remove();
    }
}

// Canvas normalises any CSS colour it can parse: paint one pixel and read
// it back as RGB, then format as `#rrggbb`. Reading the pixel, not the
// `fillStyle` getter, is the point — modern Chrome serialises fillStyle in
// the syntax it was given (`oklch(…)`, `lab(…)`), which zrender cannot
// parse; on hover its `liftColor` then returns undefined and the series
// vanishes. Falls back to the input when canvas is unavailable (jsdom).
let context: CanvasRenderingContext2D | null | undefined;

function toHex(color: string): string {
    if (context === undefined) {
        const canvas = document.createElement("canvas");
        canvas.width = 1;
        canvas.height = 1;
        context = canvas.getContext("2d", { willReadFrequently: true });
    }
    if (!context) return color;
    context.clearRect(0, 0, 1, 1);
    context.fillStyle = color;
    context.fillRect(0, 0, 1, 1);
    const pixel = context.getImageData(0, 0, 1, 1).data;
    // Alpha 0 means the colour did not parse (nothing was painted).
    if (pixel[3] === 0) return color;
    const hex = (index: number) =>
        (pixel[index] ?? 0).toString(16).padStart(2, "0");
    return `#${hex(0)}${hex(1)}${hex(2)}`;
}

"use client";

import type { EChartsOption } from "echarts";
import EChartsReact from "echarts-for-react";
import * as React from "react";
import { type ThemeTokens, useThemeTokens } from "@/hooks/use-theme-tokens";
import { cn } from "@/lib/cn";

// Chart — an ECharts wrapper that resolves the active theme's tokens and
// applies them to the chart's axes, series and tooltip.
//
// The chart tokens are a separate axis from the palette contract
// (architecture.md §5): no role describes "the third series", and reusing
// danger as series 4 breaks its meaning. The categorical derivation
// (chart-1 through chart-8) lives in global.css as theme machinery, derived
// from --palette-base via oklch(from ...).
//
// This wrapper does three things:
// 1. Reads the theme tokens via useThemeTokens, scoped to its own element
//    (re-reads on theme change). Because the read is scoped, a palette
//    class on the chart — `className="palette-blue"` — re-derives the
//    series colours from that palette for this chart alone.
// 2. Merges them into the option's axis, series and tooltip colours
// 3. Renders ECharts with the merged option
//
// It does NOT re-implement ECharts' API — the consumer passes a full
// EChartsOption, and the wrapper only injects colours. This keeps the
// wrapper thin and avoids locking consumers out of ECharts' features.
//
// Sizing: the wrapper is `w-full` only. ECharts reads its height from the
// parent, so the consumer gives the chart a height (`className="h-72"`).

export type ChartProps = {
    option: EChartsOption;
    className?: string;
    /** X-axis categories for the convenience shorthand. */
    categories?: string[];
};

export function Chart({ option, className, categories }: ChartProps) {
    const scope = React.useRef<HTMLDivElement>(null);
    const tokens = useThemeTokens(scope);
    const merged = React.useMemo(
        () => (tokens ? mergeTheme(option, tokens, { categories }) : null),
        [option, tokens, categories],
    );

    return (
        <div
            ref={scope}
            data-slot="chart"
            className={cn("w-full", className as string)}
        >
            {/* Tokens live on the DOM: nothing to draw until they are read.
                Rendering with empty colours is the silent failure this
                replaces — ECharts draws every series in "" and shows a
                blank plot. */}
            {merged ? (
                <EChartsReact
                    option={merged}
                    style={{ height: "100%", width: "100%" }}
                    opts={{ renderer: "svg" }}
                    notMerge
                    lazyUpdate
                />
            ) : null}
        </div>
    );
}

type Loose = Record<string, unknown>;

function asObject(value: unknown): Loose | undefined {
    return value && typeof value === "object" && !Array.isArray(value)
        ? (value as Loose)
        : undefined;
}

function mergeTheme(
    option: EChartsOption,
    tokens: ThemeTokens,
    shorthand: Pick<ChartProps, "categories">,
): EChartsOption {
    const { categorical, palette } = tokens;
    const { categories } = shorthand;

    // Series colours: one categorical slot per series, in order. A series
    // coloured per data item (pie, or `colorBy: "data"`) is left alone so
    // the top-level `color` palette applies slice by slice — a single
    // series colour would paint every slice the same.
    const rawSeries = option.series;
    const seriesList = (
        Array.isArray(rawSeries) ? rawSeries : rawSeries ? [rawSeries] : []
    ) as Loose[];
    const series = seriesList.map((s, i) =>
        s.color || s.type === "pie" || s.colorBy === "data"
            ? s
            : { ...s, color: categorical[i % categorical.length] },
    );

    const axisStyle = {
        axisLine: { lineStyle: { color: palette.line } },
        axisTick: { lineStyle: { color: palette.line } },
        axisLabel: { color: palette.accent },
        splitLine: { lineStyle: { color: palette.line } },
    };

    // Axes are injected only for cartesian charts. A pie has none, and
    // handing it a value axis draws an empty grid behind the donut.
    const isCartesian = Boolean(categories || option.xAxis || option.yAxis);
    const xAxis = isCartesian
        ? {
              type: "category",
              ...(categories ? { data: categories } : {}),
              ...axisStyle,
              ...asObject(option.xAxis),
          }
        : option.xAxis;
    const yAxis = isCartesian
        ? { type: "value", ...axisStyle, ...asObject(option.yAxis) }
        : option.yAxis;

    const title = asObject(option.title);
    const legend = asObject(option.legend);

    // Text roles: the chart draws on whatever floor it sits on, which is a
    // foreign background for the chart's own palette — so every label is
    // `accent`, never `contrast` (content on a base YOU painted; in a
    // chromatic scope that is white on white). The tooltip is a soft box:
    // soft + line + accent, the same trio as a soft badge.
    return {
        color: categorical,
        textStyle: { color: palette.accent },
        ...option,
        title: title && {
            ...title,
            textStyle: {
                color: palette.accent,
                fontWeight: 600,
                ...asObject(title.textStyle),
            },
        },
        legend: legend && {
            textStyle: { color: palette.accent },
            ...legend,
        },
        tooltip: {
            backgroundColor: palette.soft,
            borderColor: palette.line,
            textStyle: { color: palette.accent },
            ...asObject(option.tooltip),
        },
        xAxis,
        yAxis,
        series,
    } as EChartsOption;
}
